import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"离世","description":"","frontmatter":{"title":"离世","date":"2026-11-24T00:00:00.000Z","seq":49,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"逢纷","link":"/blogs/楚辞/逢纷.html"},"next":{"text":"九叹·怨思","link":"/blogs/楚辞/九叹·怨思.html"}},"headers":[],"relativePath":"blogs/楚辞/离世.md","filePath":"blogs/楚辞/离世.md"}'),o={name:"blogs/楚辞/离世.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="离世" tabindex="-1">离世 <a class="header-anchor" href="#离世" aria-label="Permalink to &quot;离世&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">灵怀其不吾知兮，灵怀其不吾闻。</p><p class="poem-stanza">就灵怀之皇祖兮，愬灵怀之鬼神。</p><p class="poem-stanza">灵怀曾不吾与兮，即听夫人之谀辞。</p><p class="poem-stanza">余辞上参于天坠兮，旁引之于四时。</p><p class="poem-stanza">指日月使延照兮，抚招摇以质正。</p><p class="poem-stanza">立师旷俾端辞兮，命咎繇使并听。</p><p class="poem-stanza">兆出名曰正则兮，卦发字曰灵均。</p><p class="poem-stanza">余幼既有此鸿节兮，长愈固而弥纯。</p><p class="poem-stanza">不从俗而诐行兮，直躬指而信志。</p><p class="poem-stanza">不枉绳以追曲兮，屈情素以从事。</p><p class="poem-stanza">端余行其如玉兮，述皇舆之踵迹。</p><p class="poem-stanza">群阿容以晦光兮，皇舆覆以幽辟。</p><p class="poem-stanza">舆中涂以回畔兮，驷马惊而横奔。</p><p class="poem-stanza">执组者不能制兮，必折轭而摧辕。</p><p class="poem-stanza">断镳衔以驰骛兮，暮去次而敢止。</p><p class="poem-stanza">路荡荡其无人兮，遂不禦乎千里。</p><p class="poem-stanza">身衡陷而下沉兮，不可获而复登。</p><p class="poem-stanza">不顾身之卑贱兮，惜皇舆之不兴。</p><p class="poem-stanza">出国门而端指兮，冀壹寤而锡还。</p><p class="poem-stanza">哀仆夫之坎毒兮，屡离忧而逢患。</p><p class="poem-stanza">九年之中不吾反兮，思彭咸之水游。</p><p class="poem-stanza">惜师延之浮渚兮，赴汨罗之长流。</p><p class="poem-stanza">遵江曲之逶移兮，触石碕而衡游。</p><p class="poem-stanza">波澧澧而扬浇兮，顺长濑之浊流。</p><p class="poem-stanza">凌黄沱而下低兮，思还流而复反。</p><p class="poem-stanza">玄舆驰而并集兮，身容与而日远。</p><p class="poem-stanza">棹舟杭以横濿兮，济湘流而南极。</p><p class="poem-stanza">立江界而长吟兮，愁哀哀而累息。</p><p class="poem-stanza">情慌忽以忘归兮，神浮游以高历。</p><p class="poem-stanza">心蛩蛩而怀顾兮，魂眷眷而独逝。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">余思旧邦心依违兮，日暮黄昏羌幽悲兮，</p><p class="poem-stanza">去郢东迁余谁慕兮，谗夫党旅其以兹故兮，</p><p class="poem-stanza">河水淫淫情所愿兮，顾瞻郢路终不返兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
